mapper.select:
SELECT

FROM xsy_print_customer_template
WHERE customer_id = #{customerId}
    AND document_type = #{documentType}
    AND deleted = FALSE

SELECT b.id, b.customer_id AS customerId, c.name AS customerName, b.document_type AS documentType, b.template_id AS templateId, t.template_code AS templateCode, t.template_name AS templateName, t.enabled_flag AS templateEnabled, b.version, b.updated_at AS updatedAt FROM xsy_print_customer_template b JOIN xsy_customer c ON c.id = b.customer_id AND c.deleted = FALSE JOIN xsy_print_template t ON t.id = b.template_id AND t.deleted = FALSE WHERE b.deleted = FALSE AND b.document_type = #{documentType} AND b.customer_id = #{customerId}
AND FALSE
AND c.seller_id IN #{scopeId}
ORDER BY b.updated_at DESC, b.id DESC

mapper.update:
UPDATE xsy_print_customer_template
SET template_id = #{templateId}, version = version + 1, updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{id}
    AND deleted = FALSE

UPDATE xsy_print_customer_template
SET deleted = TRUE, version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE customer_id = #{customerId}
    AND document_type = #{documentType}
    AND deleted = FALSE
